'use strict';

/**
 * CSV helpers with spreadsheet formula-injection protection.
 *
 * Text cells that begin with = + - @ tab or carriage return are prefixed with a
 * single quote so Excel/Sheets treat them as text. Numbers generated by the
 * server are written raw (a negative number must stay a number).
 */
function csvCell(value) {
    if (value === null || value === undefined) {
        return '';
    }
    if (typeof value === 'number') {
        return Number.isFinite(value) ? String(value) : '';
    }
    let text = String(value);
    if (/^[=+\-@\t\r\n]/.test(text)) {
        text = `'${text}`;
    }
    if (/[",\r\n]/.test(text)) {
        text = `"${text.replace(/"/g, '""')}"`;
    }
    return text;
}

/** columns: [{ header, key }]; rows: plain objects. */
function toCsv(columns, rows) {
    const lines = [columns.map((c) => csvCell(c.header)).join(',')];
    for (const row of rows) {
        lines.push(columns.map((c) => csvCell(row[c.key])).join(','));
    }
    return `${lines.join('\r\n')}\r\n`;
}

module.exports = { csvCell, toCsv };
